const listCompanySuggestionReviewIDs = `-- name: ListCompanySuggestionReviewIDs :many
SELECT id
FROM suggestions
WHERE status IN ('pending', 'partially_applied')
ORDER BY created_at DESC
`

func (q *Queries) ListCompanySuggestionReviewIDs(ctx context.Context) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, listCompanySuggestionReviewIDs)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

