func (q *Queries) ListCompanySuggestionReviews(ctx context.Context, arg ListCompanySuggestionReviewsParams) ([]ListCompanySuggestionReviewsRow, error) {
	rows, err := q.db.Query(ctx, listCompanySuggestionReviews,
		arg.Status,
		arg.SourceType,
		arg.Q,
		arg.Offset,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListCompanySuggestionReviewsRow
	for rows.Next() {
		var i ListCompanySuggestionReviewsRow
		if err := rows.Scan(
			&i.ID,
			&i.TargetCompanyID,
			&i.CreatedCompanyID,
			&i.SourceID,
			&i.SourceType,
			&i.SourceInputTable,
			&i.SourceInputID,
			&i.SourceNativeID,
			&i.SourcePayloadHash,
			&i.Confidence,
			&i.Status,
			&i.CreatedAt,
			&i.CompanyName,
			&i.ProposedName,
			&i.RegistrationNumber,
			&i.Lei,
			&i.CountryID,
			&i.TotalCount,
			&i.PendingCount,
			&i.AppliedCount,
			&i.RejectedCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listPendingCompanySuggestionReviewItems = `-- name: ListPendingCompanySuggestionReviewItems :many
SELECT section_table, id
FROM (
    SELECT 1 AS section_order, 'suggestion_company_profiles'::text AS section_table, scp.id, scp.created_at
    FROM suggestion_company_profiles scp
    WHERE scp.suggestion_id = $1::uuid AND scp.status = 'pending'
    UNION ALL
    SELECT 2, 'suggestion_company_domains'::text, scd.id, scd.created_at
    FROM suggestion_company_domains scd
    WHERE scd.suggestion_id = $1::uuid AND scd.status = 'pending'
    UNION ALL
    SELECT 3, 'suggestion_company_locations'::text, scl.id, scl.created_at
    FROM suggestion_company_locations scl
    WHERE scl.suggestion_id = $1::uuid AND scl.status = 'pending'
    UNION ALL
    SELECT 4, 'suggestion_company_emails'::text, sce.id, sce.created_at
    FROM suggestion_company_emails sce
    WHERE sce.suggestion_id = $1::uuid AND sce.status = 'pending'
    UNION ALL
    SELECT 5, 'suggestion_company_phones'::text, scp2.id, scp2.created_at
    FROM suggestion_company_phones scp2
    WHERE scp2.suggestion_id = $1::uuid AND scp2.status = 'pending'
    UNION ALL
    SELECT 6, 'suggestion_company_financials'::text, scf.id, scf.created_at
    FROM suggestion_company_financials scf
    WHERE scf.suggestion_id = $1::uuid AND scf.status = 'pending'
    UNION ALL
    SELECT 7, 'suggestion_company_industries'::text, sci.id, sci.created_at
    FROM suggestion_company_industries sci
    WHERE sci.suggestion_id = $1::uuid AND sci.status = 'pending'
    UNION ALL
    SELECT 8, 'suggestion_company_markets'::text, scm.id, scm.created_at
    FROM suggestion_company_markets scm
    WHERE scm.suggestion_id = $1::uuid AND scm.status = 'pending'
    UNION ALL
    SELECT 9, 'suggestion_company_services'::text, scs.id, scs.created_at
    FROM suggestion_company_services scs
    WHERE scs.suggestion_id = $1::uuid AND scs.status = 'pending'
    UNION ALL
    SELECT 10, 'suggestion_company_relationships'::text, scr.id, scr.created_at
    FROM suggestion_company_relationships scr
    WHERE scr.suggestion_id = $1::uuid AND scr.status = 'pending'
) pending_items
ORDER BY section_order, created_at, id
`

type ListPendingCompanySuggestionReviewItemsRow struct {
	SectionTable string    `json:"section_table"`
	ID           uuid.UUID `json:"id"`
}

func (q *Queries) ListPendingCompanySuggestionReviewItems(ctx context.Context, suggestionID uuid.UUID) ([]ListPendingCompanySuggestionReviewItemsRow, error) {
	rows, err := q.db.Query(ctx, listPendingCompanySuggestionReviewItems, suggestionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListPendingCompanySuggestionReviewItemsRow
	for rows.Next() {
		var i ListPendingCompanySuggestionReviewItemsRow
		if err := rows.Scan(&i.SectionTable, &i.ID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

