const updateSuggestionAggregateStatus = `-- name: UpdateSuggestionAggregateStatus :exec
UPDATE suggestions
SET status = $2,
    reviewed_by = $3,
    reviewed_at = CASE WHEN $2 IN ('applied', 'rejected') THEN now() ELSE reviewed_at END,
    review_note = $4,
    updated_at = now()
WHERE id = $1
`

